import { Component, OnInit, ElementRef, ViewChild, HostListener } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms'; 
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';
import { NotificationService } from '../../services/notification';
import { ApiService } from '../../services/api-service';
import { ChangeDetectorRef } from '@angular/core';
import { ACADEMIC_YEAR } from '../../services/constant';
import { baseApiUrl } from '../../constants/constant';
import autoTable from 'jspdf-autotable'; 
 import {SCHOOL_CONTACTS} from '../../constants/constant'

export interface Student {
  id: number; 
  srNumber: string;
  name: string;
  fathersName: string;
  mothersName: string;
  aadharNumber: string;
  phoneNumber: string;
  standard: string;
  dob: string;
  address: string;
  photoUrl: string;
  createdAt: string;
  updatedAt: string;
  avatar?: string; 
}

@Component({
  selector: 'app-students',
  standalone: true,
  imports: [CommonModule, FormsModule,],
  templateUrl: './student.html',
  styleUrls: ['./student.css']
})
export class StudentsComponent implements OnInit {
  
  @ViewChild('idCardElement', { static: false }) idCardElement!: ElementRef;

  // --- REPLACE THESE WITH YOUR ACTUAL BASE64 STRINGS ---
  readonly schoolLogoBase64: string =  'data:image/jpeg;base64,'; ; 
  readonly principalSignBase64: string = 'data:image/png;base64,'
  readonly schoolContacts: string = SCHOOL_CONTACTS; 
  // -----------------------------------------------------

  readonly defaultAvatar: string = "data:image/svg+xml;charset=UTF-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%2394a3b8'%3E%3Cpath d='M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z'/%3E%3C/svg%3E";
  selectedGrade: string = ''; 
  searchText: string = '';
  currentPage: number = 1;
  pageSize: number = 32; 
  isLoading: boolean = false; 
  
  isSidePanelOpen: boolean = false;
  panelMode: 'add' | 'edit' = 'add';
  currentStudent: Partial<Student> = {}; 
  formErrors: any = {}; 
  academicYear = ACADEMIC_YEAR;
  showIdModal: boolean = false;
  generatedStudent: Student | null = null;
  allStudents: Student[] = [];
  totalItems: number = 0;
  totalPages: number = 0;

  constructor(
    private notificationService: NotificationService,
    private studentService: ApiService,
    private cdr: ChangeDetectorRef
  ) {}

  selectedPhotoFile: File | null = null;
  photoPreviewUrl: string | ArrayBuffer | null = null;

  standards: any[] = [
    { label: 'Grade PG', value: 'PG' },
    { label: 'Grade LKG', value: 'LKG' },
    { label: 'Grade UKG', value: 'UKG' },
    { label: 'Grade 1', value: '1' },
    { label: 'Grade 2', value: '2' },
    { label: 'Grade 3', value: '3' },
    { label: 'Grade 4', value: '4' },
    { label: 'Grade 5', value: '5' },
    { label: 'Grade 6', value: '6' },
    { label: 'Grade 7', value: '7' },
    { label: 'Grade 8', value: '8' },
    { label: 'Grade 9', value: '9' },
    { label: 'Grade 10', value: '10' },
    { label: 'Grade 11', value: '11' },
  ];

  ngOnInit(): void {}

  onFilterChange(): void { 
    this.currentPage = 1; 
    if (this.selectedGrade) {
      this.loadStudentsByGrade(this.selectedGrade);
    } else {
      this.allStudents = [];
    }
  }

  loadStudentsByGrade(grade: string): void {
    this.isLoading = true;
    this.studentService.getStudentsByGrade(grade, this.searchText, this.currentPage - 1, this.pageSize).subscribe({
      next: (response: any) => {
        this.allStudents = response.data.content || [];
        this.totalItems = response.data.totalElements;
        this.totalPages = response.data.totalPages;
        
        this.allStudents.forEach(s => {
           if (s.photoUrl) {
             s.avatar = `${baseApiUrl}api/students/photos/${s.photoUrl}`; 
           } else {
             s.avatar = this.defaultAvatar;
           }
        });
        this.isLoading = false;
        this.cdr.detectChanges();
      },
      error: (err: any) => {
        console.error(err);
        this.notificationService.showError(`Failed to load students for Grade ${grade}.`);
        this.isLoading = false;
        this.allStudents = [];
        this.totalItems = 0;
        this.cdr.detectChanges();
      }
    });
  }

  validateForm(): boolean {
    this.formErrors = {};
    let isValid = true;
    if (!this.currentStudent.standard) { this.formErrors.standard = 'Standard/Grade is required'; isValid = false; }
    if (!this.currentStudent.name?.trim()) { this.formErrors.name = 'Full Name is required'; isValid = false; }
    if (!this.currentStudent.fathersName?.trim()) { this.formErrors.fathersName = 'Father\'s Name is required'; isValid = false; }
    if (!this.currentStudent.mothersName?.trim()) { this.formErrors.mothersName = 'Mother\'s Name is required'; isValid = false; }
    if (!this.currentStudent.phoneNumber?.trim()) { this.formErrors.phoneNumber = 'Phone Number is required'; isValid = false; }
    if (!this.currentStudent.dob) { this.formErrors.dob = 'Date of Birth is required'; isValid = false; }
    return isValid;
  }

  saveStudent(): void {
    if (!this.validateForm()) {
      this.notificationService.showError('Please fill in all mandatory fields.');
      return;
    }
    this.isLoading = true; 
    if (this.panelMode === 'add') {
      this.studentService.addStudent(this.currentStudent).subscribe({
        next: (response: any) => { this.handlePhotoUploadAndFinalize(response.data.id, response.message, response.data); },
        error: (err: any) => { this.notificationService.showError(err.error?.message || 'Error adding student'); this.isLoading = false; this.cdr.detectChanges(); }
      });
    } else {
      this.studentService.updateStudent(this.currentStudent.id!.toString(), this.currentStudent).subscribe({
        next: (response: any) => { this.handlePhotoUploadAndFinalize(this.currentStudent.id!, response.message, response.data); },
        error: (err: any) => { this.notificationService.showError(err.error?.message || 'Error updating student'); this.isLoading = false; this.cdr.detectChanges(); }
      });
    }
  }

  private handlePhotoUploadAndFinalize(studentId: number, successMsg: string, studentData: any): void {
    if (this.selectedPhotoFile) {
      this.studentService.uploadStudentPhoto(studentId, this.selectedPhotoFile).subscribe({
        next: () => { this.finalizeSaveProcess(successMsg, studentData); },
        error: () => { this.notificationService.showError("Student saved, but photo upload failed."); this.finalizeSaveProcess(successMsg, studentData); }
      });
    } else {
      this.finalizeSaveProcess(successMsg, studentData);
    }
  }

  private finalizeSaveProcess(successMsg: string, studentData: any): void {
    this.notificationService.showSuccess(successMsg);
    this.closePanel();
    if (this.selectedGrade) this.loadStudentsByGrade(this.selectedGrade); 
    if (this.panelMode === 'add') { this.openIdModal(studentData); }
    this.isLoading = false;
    this.cdr.detectChanges();
  }

  deleteStudent(student: Student): void {
    if(confirm(`Are you sure you want to delete ${student.name}'s record? This cannot be undone.`)) {
      this.isLoading = true;
      this.studentService.deleteStudent(student.id.toString()).subscribe({
        next: (response: any) => {
          this.notificationService.showSuccess(response.message);
          if (this.selectedGrade) this.loadStudentsByGrade(this.selectedGrade);
          if (this.pagedStudents.length === 1 && this.currentPage > 1) this.currentPage--;
          this.isLoading = false;
          this.cdr.detectChanges();
        },
        error: (err: any) => {
          this.notificationService.showError(err.error?.message || 'Error deleting student');
          this.isLoading = false;
          this.cdr.detectChanges();
        }
      });
    }
  }

  downloadTemplate(): void {
    this.studentService.downloadTemplate().subscribe({
      next: (blob: any) => {
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'student_bulk_upload_template.xlsx';
        a.click();
        window.URL.revokeObjectURL(url);
      }
    });
  }

  onFileSelected(event: any): void {
    if (!this.selectedGrade) {
      this.notificationService.showError('Please select a Grade from the dropdown before uploading.');
      event.target.value = ''; 
      return;
    }
    const file: File = event.target.files[0];
    if (file) {
      this.isLoading = true;
      this.studentService.uploadBulk(file, this.selectedGrade).subscribe({
        next: (response: any) => {
          this.notificationService.showSuccess(response.message);
          this.loadStudentsByGrade(this.selectedGrade); 
          this.isLoading = false;
          this.cdr.detectChanges();
        },
        error: (err: any) => {
          this.notificationService.showError(err.error?.message || 'Upload failed.');
          this.isLoading = false;
          this.cdr.detectChanges();
        }
      });
      event.target.value = ''; 
    }
  }

  get filteredStudents(): Student[] {
    if (!this.selectedGrade) return [];
    let result = this.allStudents; 
    if (this.searchText) {
      const search = this.searchText.toLowerCase().trim();
      result = result.filter(s => 
        (s.name && s.name.toLowerCase().includes(search)) || 
        (s.srNumber && s.srNumber.toLowerCase().includes(search)) ||
        (s.phoneNumber && s.phoneNumber.includes(search))
      );
    }
    return result;
  }
  
  get startIndex(): number { return (this.currentPage - 1) * this.pageSize; }
  get endIndex(): number { return Math.min(this.startIndex + this.pageSize, this.totalItems); }
  goToPage(page: number): void { 
    if (page >= 1 && page <= this.totalPages) {
      this.currentPage = page;
      this.loadStudentsByGrade(this.selectedGrade); 
    } 
  }

  get pagedStudents(): Student[] { return this.allStudents; }
  get pages(): number[] { return Array.from({ length: this.totalPages }, (_, i) => i + 1); }

  openPanel(mode: 'add' | 'edit', student?: Student): void {
    this.panelMode = mode;
    this.formErrors = {}; 
    this.selectedPhotoFile = null; 
    this.photoPreviewUrl = null;   
    
    if (mode === 'edit' && student) {
      this.currentStudent = { ...student };
    } else {
      this.currentStudent = { standard: '' };
    }
    this.isSidePanelOpen = true;
  }

  closePanel(): void { this.isSidePanelOpen = false; this.currentStudent = {}; this.formErrors = {}; }
  openAddStudentModal(): void { this.openPanel('add'); }
  viewStudentProfile(student: Student): void { this.notificationService.showSuccess(`Loading profile view...`); }
  downloadIdCardFromTable(student: Student): void { this.openIdModal(student); }
  openIdModal(student: Student): void { this.generatedStudent = student; this.showIdModal = true; }
  closeIdModal(): void { this.showIdModal = false; this.generatedStudent = null; }
  
  downloadIdCardPDF(): void {
    if (!this.idCardElement) return;
    this.notificationService.showSuccess('Preparing high-quality ID Card...');
    const element = this.idCardElement.nativeElement;
    html2canvas(element, { scale: 3, useCORS: true, backgroundColor: '#ffffff' }).then((canvas) => {
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('portrait', 'mm', [54, 86]); 
      pdf.addImage(imgData, 'PNG', 0, 0, 54, 86);
      pdf.save(`${this.generatedStudent?.name?.replace(/\s+/g, '_')}_ID_Card.pdf`);
      this.closeIdModal();
    });
  }

  onPhotoSelected(event: any): void {
    const file: File = event.target.files[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        this.notificationService.showError("Image is too large. Maximum size is 2MB.");
        event.target.value = ''; 
        return;
      }
      this.selectedPhotoFile = file;
      const reader = new FileReader();
      reader.onload = e => this.photoPreviewUrl = reader.result;
      reader.readAsDataURL(file);
    }
  }

  // ==========================================
  // BULK ID GENERATION
  // ==========================================
  isGenerating: boolean = false;

  async generateBulkIDs(): Promise<void> {
    if (!this.allStudents?.length) {
      this.notificationService.showError('No students found.');
      return;
    }

    this.isGenerating = true;
    this.cdr.detectChanges();
    this.notificationService.showSuccess('Preparing ID cards…');

    try {
      const imageMap = await this.preloadStudentImages();

      const pdf     = new jsPDF('l', 'mm', 'a4');
      const cols    = 4, rows = 2;
      const cardW   = 54, cardH = 86;
      const gapX    = 5,  gapY  = 6;
      const totalW  = cols * cardW + (cols - 1) * gapX; 
      const totalH  = rows * cardH + (rows - 1) * gapY; 
      const startX  = (297 - totalW) / 2;                 
      const startY  = (210 - totalH) / 2;                 
      const perPage = cols * rows;                         

      for (let i = 0; i < this.allStudents.length; i++) {
        const pos = i % perPage;
        if (i > 0 && pos === 0) pdf.addPage();

        const col = pos % cols;
        const row = Math.floor(pos / cols);
        const x   = startX + col * (cardW + gapX);
        const y   = startY + row * (cardH + gapY);

        this.drawIdCard(pdf, this.allStudents[i], x, y, cardW, cardH, imageMap.get(this.allStudents[i].id) ?? null);
      }

      pdf.save(`ID_Cards_Grade_${this.selectedGrade}_${this.academicYear}.pdf`);
      this.notificationService.showSuccess(`✅ ${this.allStudents.length} ID cards generated!`);
    } catch (err) {
      console.error(err);
      this.notificationService.showError('Failed to generate ID cards.');
    } finally {
      this.isGenerating = false;
      this.cdr.detectChanges();
    }
  }

  private async preloadStudentImages(): Promise<Map<number, string | null>> {
    const map = new Map<number, string | null>();
    const load = async (s: Student): Promise<void> => {
      if (!s.photoUrl) { map.set(s.id, null); return; }
      try {
        const res  = await fetch(`${baseApiUrl}api/students/photos/${s.photoUrl}`, { mode: 'cors', cache: 'force-cache' });
        if (!res.ok) throw new Error();
        const blob = await res.blob();
        const b64  = await new Promise<string>((ok, fail) => {
          const r = new FileReader();
          r.onloadend = () => ok(r.result as string);
          r.onerror   = fail;
          r.readAsDataURL(blob);
        });
        map.set(s.id, b64);
      } catch { map.set(s.id, null); }
    };

    for (let i = 0; i < this.allStudents.length; i += 5)
      await Promise.all(this.allStudents.slice(i, i + 5).map(load));

    return map;
  }

  private drawIdCard(
    pdf: jsPDF, s: Student,
    x: number, y: number, w: number, h: number,
    imgData: string | null
  ): void {
    // Card Base
    pdf.setFillColor(255, 255, 255);
    pdf.rect(x, y, w, h, 'F');
    pdf.setDrawColor(226, 232, 240);
    pdf.setLineWidth(0.25);
    pdf.rect(x, y, w, h, 'S');

    // ════════════════════════════════════════════════════════════════════════
    // HEADER WITH LOGO & EXTREME SCALED CONTACT TEXT
    // ════════════════════════════════════════════════════════════════════════
    pdf.setFillColor(0, 0, 128);   
    const headerHeight = 15;
    pdf.rect(x, y, w, headerHeight, 'F');

    const logoSize = 10;
    pdf.addImage(this.schoolLogoBase64, 'PNG', x + 3, y + 2.5, logoSize, logoSize);

    // School name 
    pdf.setTextColor(255, 255, 255);
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(8); 
    pdf.text('S.B. PUBLIC SCHOOL', x + w / 2 + 4, y + 5.5, { align: 'center' });

    // Subtitle
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(5.5);
    pdf.setTextColor(210, 210, 255); 
    pdf.text(`Identity Card | ${this.academicYear}`, x + w / 2 + 4, y + 9, { align: 'center' });

    // Contact Numbers (Aggressively dropped font size to ensure fit)
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(4.0); 
    pdf.setTextColor(255, 255, 255);
    pdf.text(this.schoolContacts, x + w / 2 + 4, y + 12.5, { align: 'center' });

    // ════════════════════════════════════════════════════════════════════════
    // PHOTO ROW 
    // ════════════════════════════════════════════════════════════════════════
    const photoW = 17, photoH = 19;
    const photoX = x + (w - photoW) / 2;
    const photoY = y + 17; 

    pdf.setFillColor(200, 200, 200);
    pdf.rect(photoX + 0.4, photoY + 0.4, photoW + 0.8, photoH + 0.8, 'F');
    pdf.setFillColor(255, 255, 255);
    pdf.rect(photoX - 0.6, photoY - 0.6, photoW + 1.2, photoH + 1.2, 'F');

    if (imgData) {
      try {
        const fmt = imgData.startsWith('data:image/png') ? 'PNG' : 'JPEG';
        pdf.addImage(imgData, fmt, photoX, photoY, photoW, photoH);
      } catch { this.drawPhotoPlaceholder(pdf, photoX, photoY, photoW, photoH); }
    } else {
      this.drawPhotoPlaceholder(pdf, photoX, photoY, photoW, photoH);
    }

    const sideLabelY = photoY + 6;
    pdf.setFontSize(4.5);
    pdf.setFont('helvetica', 'bold');
    pdf.setTextColor(220, 38, 38); 
    pdf.text('SESSION', x + 3, sideLabelY);
    pdf.text('S.R. No.', x + w - 3, sideLabelY, { align: 'right' });

    pdf.setFontSize(5.5);
    pdf.setTextColor(30, 41, 59);
    pdf.text(this.academicYear, x + 3, sideLabelY + 4);
    pdf.text(s.srNumber || '-', x + w - 3, sideLabelY + 4, { align: 'right' });

    // ════════════════════════════════════════════════════════════════════════
    // STUDENT NAME 
    // ════════════════════════════════════════════════════════════════════════
    const nameY = photoY + photoH + 5; 
    pdf.setFontSize(10);
    pdf.setFont('helvetica', 'bold');
    pdf.setTextColor(0, 0, 128); 
    pdf.text((s.name || '').toUpperCase(), x + w / 2, nameY, { align: 'center' });

    // ════════════════════════════════════════════════════════════════════════
    // GRADE PILL
    // ════════════════════════════════════════════════════════════════════════
    const gradeStr = `Grade: ${s.standard}`;
    pdf.setFontSize(7);
    const pillW = pdf.getTextWidth(gradeStr) + 5;
    const pillH = 4.5;
    const gradeY = nameY + 5;
    const pillX = x + (w - pillW) / 2;

    pdf.setFillColor(240, 240, 255);
    pdf.roundedRect(pillX, gradeY - 3.2, pillW, pillH, 1, 1, 'F');
    pdf.setTextColor(0, 0, 128);
    pdf.text(gradeStr, x + w / 2, gradeY, { align: 'center' });

    // ════════════════════════════════════════════════════════════════════════
    // DETAILS GRID
    // ════════════════════════════════════════════════════════════════════════
  // ════════════════════════════════════════════════════════════════════════
    // DETAILS GRID
    // ════════════════════════════════════════════════════════════════════════
    const divY = gradeY + 3;
    pdf.setDrawColor(200, 200, 200);
    pdf.setLineDashPattern([0.5, 0.5], 0);
    pdf.line(x + 5, divY, x + w - 5, divY);
    pdf.setLineDashPattern([], 0);

    let detY = divY + 3.5;
    const rowGap = 3.6; 

    const details = [
      { label: 'Father:', value: s.fathersName || '-' },
      { label: 'Mother:', value: s.mothersName || '-' },
      { label: 'D.O.B:',  value: this.formatDate(s.dob) },
      { label: 'Phone:',  value: s.phoneNumber || '-' },
    ];

    for (const d of details) {
      // Label styling
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(5.5); // Slightly smaller label
      pdf.setTextColor(100, 116, 139);
      pdf.text(d.label, x + 4, detY);

      // Value styling
      pdf.setTextColor(30, 41, 59);
      pdf.setFontSize(5); // Dropped font size so 2 phone numbers fit
      
      // INCREASED limit from 22 to 30 so dual phone numbers don't get '...'
      pdf.text(this.truncate(d.value, 30), x + w - 4, detY, { align: 'right' });
      detY += rowGap;
    }

    // ════════════════════════════════════════════════════════════════════════
    // NEW FOOTER — Address and Signature Image
    // ════════════════════════════════════════════════════════════════════════
    const footerH = 17;
    const footerY = y + h - footerH;
    
    pdf.setFillColor(250, 250, 252);
    pdf.rect(x + 0.5, footerY, w - 1, footerH - 0.5, 'F');
    pdf.setDrawColor(226, 232, 240);
    pdf.line(x + 0.5, footerY, x + w - 0.5, footerY); 

    // Address (Pushed slightly up)
    pdf.setFontSize(4.5);
    pdf.setFont('helvetica', 'normal');
    pdf.setTextColor(71, 85, 105);
    const addrLines = pdf.splitTextToSize(`Add: ${s.address || 'N/A'}`, w - 4);
    pdf.text(addrLines.slice(0, 2), x + w / 2, footerY + 3.5, { align: 'center', lineHeightFactor: 1.1 });

    // Principal Signature Image (MASSIVELY INCREASED SIZE)
    const sigW = 22, sigH = 8.5; // Was 12x5!
    pdf.addImage(this.principalSignBase64, 'PNG', x + w / 2 - sigW / 2, footerY + 5.5, sigW, sigH);
    
    // Principal Text (Slightly larger and moved down)
    pdf.setFontSize(5.5);
    pdf.setTextColor(0, 0, 128);
    pdf.setFont('helvetica', 'bold');
    pdf.text('PRINCIPAL SIGN', x + w / 2, footerY + 15.5, { align: 'center' });
  }

  private drawPhotoPlaceholder(
    pdf: jsPDF, x: number, y: number, w: number, h: number
  ): void {
    pdf.setFillColor(241, 245, 249);  
    pdf.rect(x, y, w, h, 'F');
    pdf.setFontSize(4);
    pdf.setFont('helvetica', 'normal');
    pdf.setTextColor(148, 163, 184);  
    pdf.text('No Photo', x + w / 2, y + h / 2 + 0.8, { align: 'center' });
  }

  private formatDate(raw: string): string {
    if (!raw) return '-';
    try {
      const d = new Date(raw);
      return [String(d.getDate()).padStart(2,'0'),
              String(d.getMonth()+1).padStart(2,'0'),
              d.getFullYear()].join('-');
    } catch { return raw; }
  }

  private truncate(text: string, max: number): string {
    if (!text) return '';
    return text.length > max ? text.substring(0, max - 1) + '…' : text;
  }

  // ==========================================
  // ROSTER LOGIC
  // ==========================================
  showRosterModal: boolean = false;
  selectedClassesForRoster: string[] = [];
  isGeneratingRoster: boolean = false;

  openRosterModal(): void {
    this.selectedClassesForRoster = []; 
    this.showRosterModal = true;
  }

  closeRosterModal(): void {
    this.showRosterModal = false;
  }

  toggleRosterClass(gradeValue: string): void {
    const index = this.selectedClassesForRoster.indexOf(gradeValue);
    if (index > -1) {
      this.selectedClassesForRoster.splice(index, 1); 
    } else {
      this.selectedClassesForRoster.push(gradeValue); 
    }
  }

  get isAllSelected(): boolean {
    return this.standards.length > 0 && 
           this.selectedClassesForRoster.length === this.standards.length;
  }

  toggleAllRosterClasses(event: any): void {
    const isChecked = event.target.checked;
    if (isChecked) {
      this.selectedClassesForRoster = this.standards.map(std => std.value);
    } else {
      this.selectedClassesForRoster = [];
    }
  }

  async generateClassRosters(): Promise<void> {
    if (this.selectedClassesForRoster.length === 0) return;

    this.isGeneratingRoster = true;
    this.notificationService.showSuccess('Fetching data and compiling class lists...');

    try {
      const response: any = await this.studentService.getRosterByStandards(this.selectedClassesForRoster).toPromise();
      const allRosterStudents: Student[] = response?.data || [];

      if (allRosterStudents.length === 0) {
        this.notificationService.showError('No students found for the selected classes.');
        this.isGeneratingRoster = false;
        return;
      }

      const studentsByClass = allRosterStudents.reduce((acc, student) => {
        if (!acc[student.standard]) acc[student.standard] = [];
        acc[student.standard].push(student);
        return acc;
      }, {} as Record<string, Student[]>);

      const pdf = new jsPDF('l', 'mm', 'a4'); 
      const sortedClasses = this.selectedClassesForRoster.sort((a, b) => 
        this.standards.findIndex(s => s.value === a) - this.standards.findIndex(s => s.value === b)
      );

      let pageAdded = false;

      for (let i = 0; i < sortedClasses.length; i++) {
        const grade = sortedClasses[i];
        const studentsInClass = studentsByClass[grade] || [];

        if (studentsInClass.length === 0) continue;
        
        if (pageAdded) { pdf.addPage(); }

        pdf.setFontSize(16);
        pdf.setFont('helvetica', 'bold');
        pdf.setTextColor(0, 0, 128); 
        pdf.text(`S.B. PUBLIC SCHOOL - Class Roster`, 14, 20);
        
        pdf.setFontSize(12);
        pdf.setTextColor(100, 116, 139);
        pdf.text(`Grade: ${grade} | Total Students: ${studentsInClass.length} | Session: ${this.academicYear}`, 14, 28);

        const tableColumn = ["S.No.", "SR No", "Student Name", "Father's Name", "Phone Number", "DOB", "Added On", "Address"];      
        const tableRows = studentsInClass.map((s, index) => [
          index + 1, 
          s.srNumber || '-',
          s.name,
          s.fathersName || '-',
          s.phoneNumber || '-',
          s.dob ? new Date(s.dob).toLocaleDateString() : '-',
          s.createdAt ? new Date(s.createdAt).toLocaleDateString() : '-',
          s.address || '-' 
        ]);

        autoTable(pdf, {
          head: [tableColumn],
          body: tableRows,
          startY: 35, 
          theme: 'grid',
          headStyles: { fillColor: [0, 0, 128] }, 
          styles: { fontSize: 9, cellPadding: 3 },
          columnStyles: {
            0: { cellWidth: 12, halign: 'center' }, 
            7: { cellWidth: 60 } 
          }
        });
        pageAdded = true;
      }

      pdf.save(`Class_Rosters_${this.academicYear}.pdf`);
      this.notificationService.showSuccess('Class lists downloaded successfully!');

    } catch (error) {
      console.error('Error generating rosters:', error);
      this.notificationService.showError('Failed to fetch data and generate class lists.');
    } finally {
      this.isGeneratingRoster = false;
      this.closeRosterModal();
    }
  }

  // ==========================================
  // DROPDOWN STATE
  // ==========================================
  activeDropdown: string | null = null;

  toggleDropdown(menu: string): void {
    if (this.activeDropdown === menu) {
      this.activeDropdown = null; 
    } else {
      this.activeDropdown = menu; 
    }
  }

  closeDropdown(): void {
    this.activeDropdown = null;
  }

  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent) {
    const target = event.target as HTMLElement;
    if (!target.closest('.custom-dropdown')) {
      this.closeDropdown();
    }
  }
}